import { useState } from 'react';
import type { AppViewProps, Todo } from '../contracts';

let activeDraggedId: string | null = null;

export function AppView(props: AppViewProps) {
  const {
    state,
    addTodo,
    editTodo,
    toggleTodo,
    deleteTodo,
    addCategory,
    renameCategory,
    deleteCategory,
    moveTodo,
  } = props;

  const [todoTitle, setTodoTitle] = useState('');
  const [categoryName, setCategoryName] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [editingTodoId, setEditingTodoId] = useState<string | null>(null);
  const [editTodoTitle, setEditTodoTitle] = useState('');

  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
  const [editCategoryName, setEditCategoryName] = useState('');

  const [draggingId, setDraggingId] = useState<string | null>(null);

  const categories = state?.categories ?? [];
  const todos = state?.todos ?? [];

  const handleAddTodo = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = todoTitle.trim();
    if (!trimmed) return;
    try {
      addTodo(trimmed);
      setTodoTitle('');
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '添加任务失败');
    }
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = categoryName.trim();
    if (!trimmed) return;
    try {
      addCategory(trimmed);
      setCategoryName('');
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '添加分类失败');
    }
  };

  const handleToggleTodo = (id: string) => {
    try {
      toggleTodo(id);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '更新待办状态失败');
    }
  };

  const handleDeleteTodo = (id: string) => {
    try {
      deleteTodo(id);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '删除任务失败');
    }
  };

  const handleStartEditTodo = (todo: Todo) => {
    setEditingTodoId(todo.id);
    setEditTodoTitle(todo.title);
  };

  const handleSaveEditTodo = (e: React.FormEvent, id: string) => {
    e.preventDefault();
    const trimmed = editTodoTitle.trim();
    if (!trimmed) return;
    try {
      editTodo(id, trimmed);
      setEditingTodoId(null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '编辑任务失败');
    }
  };

  const handleStartRenameCategory = (id: string, name: string) => {
    setEditingCategoryId(id);
    setEditCategoryName(name);
  };

  const handleSaveRenameCategory = (e: React.FormEvent, id: string) => {
    e.preventDefault();
    const trimmed = editCategoryName.trim();
    if (!trimmed) return;
    try {
      renameCategory(id, trimmed);
      setEditingCategoryId(null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '重命名分类失败');
    }
  };

  const handleDeleteCategory = (id: string) => {
    try {
      deleteCategory(id);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '删除分类失败');
    }
  };

  const handleMoveUp = (
    todoId: string,
    categoryId: string,
    index: number,
    categoryTodos: Todo[]
  ) => {
    if (index <= 0) return;
    const beforeTodoId = categoryTodos[index - 1].id;
    try {
      moveTodo(todoId, categoryId, beforeTodoId);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  const handleMoveDown = (
    todoId: string,
    categoryId: string,
    index: number,
    categoryTodos: Todo[]
  ) => {
    if (index >= categoryTodos.length - 1) return;
    const beforeTodoId = index + 2 < categoryTodos.length ? categoryTodos[index + 2].id : null;
    try {
      moveTodo(todoId, categoryId, beforeTodoId);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  const handleMoveToCategory = (todoId: string, targetCategoryId: string) => {
    try {
      moveTodo(todoId, targetCategoryId, null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动分类失败');
    }
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    activeDraggedId = id;
    setDraggingId(id);
    e.dataTransfer.setData('text/plain', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    activeDraggedId = null;
    setDraggingId(null);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDropOnTodo = (
    e: React.DragEvent,
    targetTodoId: string,
    targetCategoryId: string
  ) => {
    e.preventDefault();
    e.stopPropagation();
    const sourceId = e.dataTransfer.getData('text/plain') || draggingId || activeDraggedId;
    activeDraggedId = null;
    setDraggingId(null);
    if (!sourceId || sourceId === targetTodoId) return;
    try {
      moveTodo(sourceId, targetCategoryId, targetTodoId);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  const handleDropOnColumn = (e: React.DragEvent, targetCategoryId: string) => {
    e.preventDefault();
    const sourceId = e.dataTransfer.getData('text/plain') || draggingId || activeDraggedId;
    activeDraggedId = null;
    setDraggingId(null);
    if (!sourceId) return;
    try {
      moveTodo(sourceId, targetCategoryId, null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  return (
    <div className="todo-app">
      <header className="app-header">
        <h1 className="app-title">待办事项</h1>
      </header>

      {error && (
        <div role="alert" className="error-banner">
          <span className="error-message">{error}</span>
          <button
            type="button"
            className="error-dismiss"
            onClick={() => setError(null)}
            aria-label="关闭错误提示"
          >
            ×
          </button>
        </div>
      )}

      <section className="forms-section">
        <form onSubmit={handleAddTodo} className="action-form">
          <input
            type="text"
            data-testid="todo-input"
            className="form-input"
            placeholder="新建待办事项..."
            value={todoTitle}
            onChange={(e) => setTodoTitle(e.target.value)}
          />
          <button
            type="submit"
            data-testid="todo-submit"
            className="btn btn-primary"
            disabled={!todoTitle.trim()}
          >
            添加待办
          </button>
        </form>

        <form onSubmit={handleAddCategory} className="action-form">
          <input
            type="text"
            data-testid="category-input"
            className="form-input"
            placeholder="新建分类..."
            value={categoryName}
            onChange={(e) => setCategoryName(e.target.value)}
          />
          <button
            type="submit"
            data-testid="category-submit"
            className="btn btn-secondary"
            disabled={!categoryName.trim()}
          >
            新建分类
          </button>
        </form>
      </section>

      <main className="board-container">
        {categories.map((category) => {
          const categoryTodos = todos.filter((t) => t.categoryId === category.id);
          const isInbox = category.id === 'inbox';

          return (
            <div
              key={category.id}
              data-testid="category-column"
              className="category-column"
              onDragOver={handleDragOver}
              onDrop={(e) => handleDropOnColumn(e, category.id)}
            >
              <div className="category-header">
                <h2 className="category-title">{category.name}</h2>
                <div className="category-meta">
                  <span className="category-count">{categoryTodos.length}</span>
                  {!isInbox && (
                    <div className="category-actions">
                      <button
                        type="button"
                        className="btn-icon"
                        onClick={() => handleStartRenameCategory(category.id, category.name)}
                        aria-label={`重命名分类 ${category.name}`}
                        title="重命名分类"
                      >
                        重命名
                      </button>
                      <button
                        type="button"
                        className="btn-icon text-danger"
                        onClick={() => handleDeleteCategory(category.id)}
                        aria-label={`删除分类 ${category.name}`}
                        title="删除分类"
                      >
                        删除
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {editingCategoryId === category.id && (
                <form
                  onSubmit={(e) => handleSaveRenameCategory(e, category.id)}
                  className="rename-category-form"
                >
                  <input
                    type="text"
                    className="form-input rename-input"
                    value={editCategoryName}
                    onChange={(e) => setEditCategoryName(e.target.value)}
                    placeholder="分类名称"
                    autoFocus
                  />
                  <div className="form-buttons">
                    <button
                      type="submit"
                      className="btn btn-sm btn-primary"
                      disabled={!editCategoryName.trim()}
                    >
                      保存
                    </button>
                    <button
                      type="button"
                      className="btn btn-sm btn-ghost"
                      onClick={() => setEditingCategoryId(null)}
                    >
                      取消
                    </button>
                  </div>
                </form>
              )}

              <div className="todos-list">
                {categoryTodos.length === 0 ? (
                  <div className="empty-placeholder">暂无任务，可拖拽至此</div>
                ) : (
                  categoryTodos.map((todo, index) => {
                    const isDragging = draggingId === todo.id;
                    const isEditing = editingTodoId === todo.id;

                    return (
                      <div
                        key={todo.id}
                        data-testid="todo-row"
                        className={`todo-row ${todo.done ? 'todo-done' : ''} ${
                          isDragging ? 'todo-dragging' : ''
                        }`}
                        draggable={!isEditing}
                        onDragStart={(e) => handleDragStart(e, todo.id)}
                        onDragEnd={handleDragEnd}
                        onDragOver={handleDragOver}
                        onDrop={(e) => handleDropOnTodo(e, todo.id, category.id)}
                      >
                        {isEditing ? (
                          <form
                            onSubmit={(e) => handleSaveEditTodo(e, todo.id)}
                            className="edit-todo-form"
                          >
                            <input
                              type="text"
                              className="form-input edit-todo-input"
                              value={editTodoTitle}
                              onChange={(e) => setEditTodoTitle(e.target.value)}
                              autoFocus
                            />
                            <div className="form-buttons">
                              <button
                                type="submit"
                                className="btn btn-sm btn-primary"
                                disabled={!editTodoTitle.trim()}
                              >
                                保存
                              </button>
                              <button
                                type="button"
                                className="btn btn-sm btn-ghost"
                                onClick={() => setEditingTodoId(null)}
                              >
                                取消
                              </button>
                            </div>
                          </form>
                        ) : (
                          <>
                            <div className="todo-main">
                              <input
                                type="checkbox"
                                data-testid="toggle-todo"
                                className="todo-checkbox"
                                checked={todo.done}
                                onChange={() => handleToggleTodo(todo.id)}
                                aria-label={`标记 "${todo.title}" 为${
                                  todo.done ? '未完成' : '已完成'
                                }`}
                              />
                              <span className="todo-title">{todo.title}</span>
                            </div>

                            <div className="todo-controls">
                              <div className="reorder-group">
                                <button
                                  type="button"
                                  className="btn-icon reorder-btn"
                                  disabled={index === 0}
                                  onClick={() =>
                                    handleMoveUp(todo.id, category.id, index, categoryTodos)
                                  }
                                  aria-label={`将待办 "${todo.title}" 上移`}
                                  title="上移"
                                >
                                  ↑
                                </button>
                                <button
                                  type="button"
                                  className="btn-icon reorder-btn"
                                  disabled={index === categoryTodos.length - 1}
                                  onClick={() =>
                                    handleMoveDown(todo.id, category.id, index, categoryTodos)
                                  }
                                  aria-label={`将待办 "${todo.title}" 下移`}
                                  title="下移"
                                >
                                  ↓
                                </button>
                              </div>

                              {categories.length > 1 && (
                                <select
                                  className="category-reorder-select"
                                  value={category.id}
                                  onChange={(e) => handleMoveToCategory(todo.id, e.target.value)}
                                  aria-label={`将待办 "${todo.title}" 移动到分类`}
                                >
                                  {categories.map((c) => (
                                    <option key={c.id} value={c.id}>
                                      {c.name}
                                    </option>
                                  ))}
                                </select>
                              )}

                              <div className="todo-actions">
                                <button
                                  type="button"
                                  className="btn-icon"
                                  onClick={() => handleStartEditTodo(todo)}
                                  aria-label={`编辑待办 "${todo.title}"`}
                                  title="编辑"
                                >
                                  编辑
                                </button>
                                <button
                                  type="button"
                                  className="btn-icon text-danger"
                                  onClick={() => handleDeleteTodo(todo.id)}
                                  aria-label={`删除待办 "${todo.title}"`}
                                  title="删除"
                                >
                                  删除
                                </button>
                              </div>
                            </div>
                          </>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          );
        })}
      </main>
    </div>
  );
}

:root {
  --bg-color: #f8fafc;
  --text-color: #0f172a;
  --text-muted: #64748b;
  --surface-color: #ffffff;
  --border-color: #e2e8f0;
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.5;
}

.todo-app {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 16px;
}

.app-title {
  margin: 0;
  font-size: 28px;
  font-weight: 700;
  color: var(--text-color);
}

.error-banner {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.error-message {
  font-size: 14px;
  font-weight: 500;
}

.error-dismiss {
  background: transparent;
  border: none;
  font-size: 20px;
  line-height: 1;
  color: #b91c1c;
  cursor: pointer;
  padding: 0 4px;
}

.forms-section {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.action-form {
  display: flex;
  gap: 8px;
  flex: 1;
  min-width: 280px;
}

.form-input {
  flex: 1;
  padding: 8px 12px;
  font-size: 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background-color: var(--surface-color);
  color: var(--text-color);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.form-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.btn {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s, opacity 0.2s;
  white-space: nowrap;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:not(:disabled):hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: #f1f5f9;
  color: #334155;
  border-color: #cbd5e1;
}

.btn-secondary:not(:disabled):hover {
  background-color: #e2e8f0;
}

.btn-sm {
  padding: 4px 10px;
  font-size: 12px;
}

.btn-ghost {
  background-color: transparent;
  color: var(--text-muted);
  border-color: var(--border-color);
}

.btn-ghost:hover {
  background-color: #f1f5f9;
}

.btn-icon {
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-size: 12px;
  padding: 4px 6px;
  cursor: pointer;
  line-height: 1;
  transition: all 0.15s;
}

.btn-icon:hover:not(:disabled) {
  background-color: #f1f5f9;
  color: var(--text-color);
}

.btn-icon:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.text-danger {
  color: var(--danger-color);
}

.text-danger:hover:not(:disabled) {
  background-color: #fef2f2;
  color: var(--danger-hover);
}

.board-container {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding-bottom: 16px;
  align-items: flex-start;
}

.category-column {
  background-color: #f1f5f9;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  width: 320px;
  min-width: 280px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  padding: 14px;
  min-height: 240px;
}

.category-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid #e2e8f0;
}

.category-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--text-color);
}

.category-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.category-count {
  background-color: #e2e8f0;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
}

.category-actions {
  display: flex;
  gap: 4px;
}

.rename-category-form {
  margin-bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.rename-input {
  width: 100%;
}

.form-buttons {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}

.todos-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-height: 100px;
}

.empty-placeholder {
  color: var(--text-muted);
  font-size: 13px;
  text-align: center;
  padding: 32px 12px;
  border: 1px dashed #cbd5e1;
  border-radius: var(--radius-md);
  pointer-events: none;
}

.todo-row {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 8px;
  cursor: grab;
  transition: box-shadow 0.2s, border-color 0.2s, opacity 0.2s;
}

.todo-row:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-md);
}

.todo-row:active {
  cursor: grabbing;
}

.todo-dragging {
  opacity: 0.45;
  border: 1px dashed var(--primary-color);
}

.todo-done .todo-title {
  text-decoration: line-through;
  color: var(--text-muted);
}

.todo-main {
  display: flex;
  align-items: center;
  gap: 10px;
}

.todo-checkbox {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: var(--primary-color);
  flex-shrink: 0;
}

.todo-title {
  font-size: 14px;
  color: var(--text-color);
  word-break: break-word;
  flex: 1;
}

.todo-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  border-top: 1px solid #f1f5f9;
  padding-top: 6px;
}

.reorder-group {
  display: flex;
  gap: 2px;
}

.reorder-btn {
  font-size: 13px;
  font-weight: 700;
  padding: 2px 6px;
}

.category-reorder-select {
  font-size: 11px;
  padding: 2px 4px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: #f8fafc;
  color: var(--text-muted);
  max-width: 90px;
}

.todo-actions {
  display: flex;
  gap: 2px;
}

.edit-todo-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.edit-todo-input {
  width: 100%;
}

@media (max-width: 768px) {
  .board-container {
    flex-direction: column;
    overflow-x: visible;
  }

  .category-column {
    width: 100%;
    min-width: 0;
  }
}

import { useState } from 'react';
import type { AppViewProps, Todo } from '../contracts';

let activeDraggedId: string | null = null;

export function AppView(props: AppViewProps) {
  const {
    state,
    addTodo,
    editTodo,
    toggleTodo,
    deleteTodo,
    addCategory,
    renameCategory,
    deleteCategory,
    moveTodo,
  } = props;

  const [todoTitle, setTodoTitle] = useState('');
  const [categoryName, setCategoryName] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [editingTodoId, setEditingTodoId] = useState<string | null>(null);
  const [editTodoTitle, setEditTodoTitle] = useState('');

  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
  const [editCategoryName, setEditCategoryName] = useState('');

  const [draggingId, setDraggingId] = useState<string | null>(null);

  const categories = state?.categories ?? [];
  const todos = state?.todos ?? [];

  const handleAddTodo = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = todoTitle.trim();
    if (!trimmed) return;
    try {
      addTodo(trimmed);
      setTodoTitle('');
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '添加任务失败');
    }
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = categoryName.trim();
    if (!trimmed) return;
    try {
      addCategory(trimmed);
      setCategoryName('');
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '添加分类失败');
    }
  };

  const handleToggleTodo = (id: string) => {
    try {
      toggleTodo(id);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '更新待办状态失败');
    }
  };

  const handleDeleteTodo = (id: string) => {
    try {
      deleteTodo(id);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '删除任务失败');
    }
  };

  const handleStartEditTodo = (todo: Todo) => {
    setEditingTodoId(todo.id);
    setEditTodoTitle(todo.title);
  };

  const handleSaveEditTodo = (e: React.FormEvent, id: string) => {
    e.preventDefault();
    const trimmed = editTodoTitle.trim();
    if (!trimmed) return;
    try {
      editTodo(id, trimmed);
      setEditingTodoId(null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '编辑任务失败');
    }
  };

  const handleStartRenameCategory = (id: string, name: string) => {
    setEditingCategoryId(id);
    setEditCategoryName(name);
  };

  const handleSaveRenameCategory = (e: React.FormEvent, id: string) => {
    e.preventDefault();
    const trimmed = editCategoryName.trim();
    if (!trimmed) return;
    try {
      renameCategory(id, trimmed);
      setEditingCategoryId(null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '重命名分类失败');
    }
  };

  const handleDeleteCategory = (id: string) => {
    try {
      deleteCategory(id);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '删除分类失败');
    }
  };

  const handleMoveUp = (
    todoId: string,
    categoryId: string,
    index: number,
    categoryTodos: Todo[]
  ) => {
    if (index <= 0) return;
    const beforeTodoId = categoryTodos[index - 1].id;
    try {
      moveTodo(todoId, categoryId, beforeTodoId);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  const handleMoveDown = (
    todoId: string,
    categoryId: string,
    index: number,
    categoryTodos: Todo[]
  ) => {
    if (index >= categoryTodos.length - 1) return;
    const beforeTodoId = index + 2 < categoryTodos.length ? categoryTodos[index + 2].id : null;
    try {
      moveTodo(todoId, categoryId, beforeTodoId);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  const handleMoveToCategory = (todoId: string, targetCategoryId: string) => {
    try {
      moveTodo(todoId, targetCategoryId, null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动分类失败');
    }
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
    activeDraggedId = id;
    setDraggingId(id);
    e.dataTransfer.setData('text/plain', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    activeDraggedId = null;
    setDraggingId(null);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDropOnTodo = (
    e: React.DragEvent,
    targetTodoId: string,
    targetCategoryId: string
  ) => {
    e.preventDefault();
    e.stopPropagation();
    const sourceId = e.dataTransfer.getData('text/plain') || draggingId || activeDraggedId;
    activeDraggedId = null;
    setDraggingId(null);
    if (!sourceId || sourceId === targetTodoId) return;
    try {
      moveTodo(sourceId, targetCategoryId, targetTodoId);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  const handleDropOnColumn = (e: React.DragEvent, targetCategoryId: string) => {
    e.preventDefault();
    const sourceId = e.dataTransfer.getData('text/plain') || draggingId || activeDraggedId;
    activeDraggedId = null;
    setDraggingId(null);
    if (!sourceId) return;
    try {
      moveTodo(sourceId, targetCategoryId, null);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : '移动任务失败');
    }
  };

  return (
    <div className="todo-app">
      <header className="app-header">
        <h1 className="app-title">待办事项</h1>
      </header>

      {error && (
        <div role="alert" className="error-banner">
          <span className="error-message">{error}</span>
          <button
            type="button"
            className="error-dismiss"
            onClick={() => setError(null)}
            aria-label="关闭错误提示"
          >
            ×
          </button>
        </div>
      )}

      <section className="forms-section">
        <form onSubmit={handleAddTodo} className="action-form">
          <input
            type="text"
            data-testid="todo-input"
            className="form-input"
            placeholder="新建待办事项..."
            value={todoTitle}
            onChange={(e) => setTodoTitle(e.target.value)}
          />
          <button
            type="submit"
            data-testid="todo-submit"
            className="btn btn-primary"
            disabled={!todoTitle.trim()}
          >
            添加待办
          </button>
        </form>

        <form onSubmit={handleAddCategory} className="action-form">
          <input
            type="text"
            data-testid="category-input"
            className="form-input"
            placeholder="新建分类..."
            value={categoryName}
            onChange={(e) => setCategoryName(e.target.value)}
          />
          <button
            type="submit"
            data-testid="category-submit"
            className="btn btn-secondary"
            disabled={!categoryName.trim()}
          >
            新建分类
          </button>
        </form>
      </section>

      <main className="board-container">
        {categories.map((category) => {
          const categoryTodos = todos.filter((t) => t.categoryId === category.id);
          const isInbox = category.id === 'inbox';

          return (
            <div
              key={category.id}
              data-testid="category-column"
              className="category-column"
              onDragOver={handleDragOver}
              onDrop={(e) => handleDropOnColumn(e, category.id)}
            >
              <div className="category-header">
                <h2 className="category-title">{category.name}</h2>
                <div className="category-meta">
                  <span className="category-count">{categoryTodos.length}</span>
                  {!isInbox && (
                    <div className="category-actions">
                      <button
                        type="button"
                        className="btn-icon"
                        onClick={() => handleStartRenameCategory(category.id, category.name)}
                        aria-label={`重命名分类 ${category.name}`}
                        title="重命名分类"
                      >
                        重命名
                      </button>
                      <button
                        type="button"
                        className="btn-icon text-danger"
                        onClick={() => handleDeleteCategory(category.id)}
                        aria-label={`删除分类 ${category.name}`}
                        title="删除分类"
                      >
                        删除
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {editingCategoryId === category.id && (
                <form
                  onSubmit={(e) => handleSaveRenameCategory(e, category.id)}
                  className="rename-category-form"
                >
                  <input
                    type="text"
                    className="form-input rename-input"
                    value={editCategoryName}
                    onChange={(e) => setEditCategoryName(e.target.value)}
                    placeholder="分类名称"
                    autoFocus
                  />
                  <div className="form-buttons">
                    <button
                      type="submit"
                      className="btn btn-sm btn-primary"
                      disabled={!editCategoryName.trim()}
                    >
                      保存
                    </button>
                    <button
                      type="button"
                      className="btn btn-sm btn-ghost"
                      onClick={() => setEditingCategoryId(null)}
                    >
                      取消
                    </button>
                  </div>
                </form>
              )}

              <div className="todos-list">
                {categoryTodos.length === 0 ? (
                  <div className="empty-placeholder">暂无任务，可拖拽至此</div>
                ) : (
                  categoryTodos.map((todo, index) => {
                    const isDragging = draggingId === todo.id;
                    const isEditing = editingTodoId === todo.id;

                    return (
                      <div
                        key={todo.id}
                        data-testid="todo-row"
                        className={`todo-row ${todo.done ? 'todo-done' : ''} ${
                          isDragging ? 'todo-dragging' : ''
                        }`}
                        draggable={!isEditing}
                        onDragStart={(e) => handleDragStart(e, todo.id)}
                        onDragEnd={handleDragEnd}
                        onDragOver={handleDragOver}
                        onDrop={(e) => handleDropOnTodo(e, todo.id, category.id)}
                      >
                        {isEditing ? (
                          <form
                            onSubmit={(e) => handleSaveEditTodo(e, todo.id)}
                            className="edit-todo-form"
                          >
                            <input
                              type="text"
                              className="form-input edit-todo-input"
                              value={editTodoTitle}
                              onChange={(e) => setEditTodoTitle(e.target.value)}
                              autoFocus
                            />
                            <div className="form-buttons">
                              <button
                                type="submit"
                                className="btn btn-sm btn-primary"
                                disabled={!editTodoTitle.trim()}
                              >
                                保存
                              </button>
                              <button
                                type="button"
                                className="btn btn-sm btn-ghost"
                                onClick={() => setEditingTodoId(null)}
                              >
                                取消
                              </button>
                            </div>
                          </form>
                        ) : (
                          <>
                            <div className="todo-main">
                              <input
                                type="checkbox"
                                data-testid="toggle-todo"
                                className="todo-checkbox"
                                checked={todo.done}
                                onChange={() => handleToggleTodo(todo.id)}
                                aria-label={`标记 "${todo.title}" 为${
                                  todo.done ? '未完成' : '已完成'
                                }`}
                              />
                              <span className="todo-title">{todo.title}</span>
                            </div>

                            <div className="todo-controls">
                              <div className="reorder-group">
                                <button
                                  type="button"
                                  className="btn-icon reorder-btn"
                                  disabled={index === 0}
                                  onClick={() =>
                                    handleMoveUp(todo.id, category.id, index, categoryTodos)
                                  }
                                  aria-label={`将待办 "${todo.title}" 上移`}
                                  title="上移"
                                >
                                  ↑
                                </button>
                                <button
                                  type="button"
                                  className="btn-icon reorder-btn"
                                  disabled={index === categoryTodos.length - 1}
                                  onClick={() =>
                                    handleMoveDown(todo.id, category.id, index, categoryTodos)
                                  }
                                  aria-label={`将待办 "${todo.title}" 下移`}
                                  title="下移"
                                >
                                  ↓
                                </button>
                              </div>

                              {categories.length > 1 && (
                                <select
                                  className="category-reorder-select"
                                  value={category.id}
                                  onChange={(e) => handleMoveToCategory(todo.id, e.target.value)}
                                  aria-label={`将待办 "${todo.title}" 移动到分类`}
                                >
                                  {categories.map((c) => (
                                    <option key={c.id} value={c.id}>
                                      {c.name}
                                    </option>
                                  ))}
                                </select>
                              )}

                              <div className="todo-actions">
                                <button
                                  type="button"
                                  className="btn-icon"
                                  onClick={() => handleStartEditTodo(todo)}
                                  aria-label={`编辑待办 "${todo.title}"`}
                                  title="编辑"
                                >
                                  编辑
                                </button>
                                <button
                                  type="button"
                                  className="btn-icon text-danger"
                                  onClick={() => handleDeleteTodo(todo.id)}
                                  aria-label={`删除待办 "${todo.title}"`}
                                  title="删除"
                                >
                                  删除
                                </button>
                              </div>
                            </div>
                          </>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          );
        })}
      </main>
    </div>
  );
}

:root {
  --bg-color: #f8fafc;
  --text-color: #0f172a;
  --text-muted: #64748b;
  --surface-color: #ffffff;
  --border-color: #e2e8f0;
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.5;
}

.todo-app {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 16px;
}

.app-title {
  margin: 0;
  font-size: 28px;
  font-weight: 700;
  color: var(--text-color);
}

.error-banner {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.error-message {
  font-size: 14px;
  font-weight: 500;
}

.error-dismiss {
  background: transparent;
  border: none;
  font-size: 20px;
  line-height: 1;
  color: #b91c1c;
  cursor: pointer;
  padding: 0 4px;
}

.forms-section {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.action-form {
  display: flex;
  gap: 8px;
  flex: 1;
  min-width: 280px;
}

.form-input {
  flex: 1;
  padding: 8px 12px;
  font-size: 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background-color: var(--surface-color);
  color: var(--text-color);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.form-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.btn {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s, opacity 0.2s;
  white-space: nowrap;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:not(:disabled):hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: #f1f5f9;
  color: #334155;
  border-color: #cbd5e1;
}

.btn-secondary:not(:disabled):hover {
  background-color: #e2e8f0;
}

.btn-sm {
  padding: 4px 10px;
  font-size: 12px;
}

.btn-ghost {
  background-color: transparent;
  color: var(--text-muted);
  border-color: var(--border-color);
}

.btn-ghost:hover {
  background-color: #f1f5f9;
}

.btn-icon {
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-size: 12px;
  padding: 4px 6px;
  cursor: pointer;
  line-height: 1;
  transition: all 0.15s;
}

.btn-icon:hover:not(:disabled) {
  background-color: #f1f5f9;
  color: var(--text-color);
}

.btn-icon:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.text-danger {
  color: var(--danger-color);
}

.text-danger:hover:not(:disabled) {
  background-color: #fef2f2;
  color: var(--danger-hover);
}

.board-container {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding-bottom: 16px;
  align-items: flex-start;
}

.category-column {
  background-color: #f1f5f9;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  width: 320px;
  min-width: 280px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  padding: 14px;
  min-height: 240px;
}

.category-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid #e2e8f0;
}

.category-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--text-color);
}

.category-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.category-count {
  background-color: #e2e8f0;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
}

.category-actions {
  display: flex;
  gap: 4px;
}

.rename-category-form {
  margin-bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.rename-input {
  width: 100%;
}

.form-buttons {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}

.todos-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-height: 100px;
}

.empty-placeholder {
  color: var(--text-muted);
  font-size: 13px;
  text-align: center;
  padding: 32px 12px;
  border: 1px dashed #cbd5e1;
  border-radius: var(--radius-md);
  pointer-events: none;
}

.todo-row {
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 8px;
  cursor: grab;
  transition: box-shadow 0.2s, border-color 0.2s, opacity 0.2s;
}

.todo-row:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-md);
}

.todo-row:active {
  cursor: grabbing;
}

.todo-dragging {
  opacity: 0.45;
  border: 1px dashed var(--primary-color);
}

.todo-done .todo-title {
  text-decoration: line-through;
  color: var(--text-muted);
}

.todo-main {
  display: flex;
  align-items: center;
  gap: 10px;
}

.todo-checkbox {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: var(--primary-color);
  flex-shrink: 0;
}

.todo-title {
  font-size: 14px;
  color: var(--text-color);
  word-break: break-word;
  flex: 1;
}

.todo-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  border-top: 1px solid #f1f5f9;
  padding-top: 6px;
}

.reorder-group {
  display: flex;
  gap: 2px;
}

.reorder-btn {
  font-size: 13px;
  font-weight: 700;
  padding: 2px 6px;
}

.category-reorder-select {
  font-size: 11px;
  padding: 2px 4px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: #f8fafc;
  color: var(--text-muted);
  max-width: 90px;
}

.todo-actions {
  display: flex;
  gap: 2px;
}

.edit-todo-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.edit-todo-input {
  width: 100%;
}

@media (max-width: 768px) {
  .board-container {
    flex-direction: column;
    overflow-x: visible;
  }

  .category-column {
    width: 100%;
    min-width: 0;
  }
}
